<?php
use App\Models\{Kelas,Siswa,TahunAjaran}; use App\Services\PenempatanSiswaKelas; use Livewire\Component;
new class extends Component { public string $tahunId=''; public string $kelasId=''; public string $search=''; public array $selected=[]; public function mount():void{$this->tahunId=(string)(TahunAjaran::aktif()->value('id')??'');}
public function save():void{$this->validate(['kelasId'=>'required|exists:kelas,id','selected'=>'required|array|min:1']);$kelas=Kelas::findOrFail($this->kelasId);foreach(Siswa::whereIn('id',$this->selected)->get() as $s)app(PenempatanSiswaKelas::class)->handle($s,$kelas);$this->selected=[];session()->flash('success','Penempatan siswa berhasil diperbarui.');}
public function with():array{return ['tahun'=>TahunAjaran::orderByDesc('nama')->get(),'kelas'=>Kelas::where('tahun_ajaran_id',$this->tahunId)->orderBy('nama')->get(),'siswa'=>Siswa::where('status','aktif')->when($this->search,fn($q)=>$q->where(fn($x)=>$x->where('nama_lengkap','like','%'.$this->search.'%')->orWhere('nis','like','%'.$this->search.'%')))->orderBy('nama_lengkap')->paginate(25)];}}; ?>
<div><div class="mb-6"><p class="text-sm font-semibold text-sky-700">Akademik</p><h1 class="page-title">Penempatan Siswa Kelas</h1><p class="page-subtitle">Pilih beberapa siswa lalu tempatkan ke satu kelas pada tahun ajaran yang sama.</p></div><form wire:submit="save"><div class="card mb-4 grid gap-4 p-4 md:grid-cols-3"><select wire:model.live="tahunId" class="form-input">@foreach($tahun as $t)<option value="{{$t->id}}">{{$t->nama}}</option>@endforeach</select><select wire:model="kelasId" class="form-input"><option value="">Pilih kelas</option>@foreach($kelas as $k)<option value="{{$k->id}}">{{$k->nama}}</option>@endforeach</select><input wire:model.live.debounce.400ms="search" class="form-input" placeholder="Cari nama atau NIS"></div><div class="table-shell"><div class="table-scroll"><table class="data-table"><thead><tr><th class="w-14">Pilih</th><th>NIS</th><th>Nama Siswa</th><th>Status</th></tr></thead><tbody>@forelse($siswa as $s)<tr><td><input type="checkbox" wire:model="selected" value="{{$s->id}}" class="size-5"></td><td>{{$s->nis??'-'}}</td><td class="font-medium">{{$s->nama_lengkap}}</td><td><span class="badge-active">Aktif</span></td></tr>@empty<tr><td colspan="4" class="py-12 text-center">Belum ada data siswa.</td></tr>@endforelse</tbody></table></div><div class="border-t p-4">{{$siswa->links()}}</div></div><div class="sticky bottom-4 mt-4 flex justify-end"><button class="btn-primary" wire:loading.attr="disabled">Tempatkan {{count($selected)}} Siswa</button></div></form></div>
